import {Quaternion,Euler,MathUtils} from 'three';
// Assets are captured by the sequence player. Prepare once; seek in O(log n).
export class SequenceSampler{
 constructor(tracks){this.keys=new Map(tracks.map(t=>[t,[...t.keys].sort((a,b)=>a.time-b.time)]));this.rotations=new Map();for(const track of tracks)if(track.type==='rotation'&&track.quaternionInterpolation){this.q??=new Quaternion();this.other??=new Quaternion();this.euler??=new Euler();const keys=this.keys.get(track),values=new Float64Array(keys.length*4);keys.forEach((key,i)=>this.q.setFromEuler(this.euler.set(...key.value.map(MathUtils.degToRad),'XYZ')).toArray(values,i*4));this.rotations.set(track,values);}}
 sample(track,time,{discrete=false,reference=false}={}){const keys=this.keys.get(track)||[];if(!keys.length)return undefined;let lo=0,hi=keys.length;while(lo<hi){const mid=(lo+hi)>>1;if(keys[mid].time<=time)lo=mid+1;else hi=mid;}const first=Math.max(0,lo-1),last=Math.min(lo,keys.length-1),a=keys[first],b=keys[last];if(reference)return lo?a.value:undefined;const copy=()=>structuredClone(a.value);if(a===b||time<=a.time||discrete||a.interpolation==='step'||typeof a.value!=='number'&&!Array.isArray(a.value))return copy();const alpha=Math.max(0,Math.min(1,(time-a.time)/(b.time-a.time))),rotations=this.rotations.get(track);if(rotations){this.q.fromArray(rotations,first*4).slerp(this.other.fromArray(rotations,last*4),alpha);this.euler.setFromQuaternion(this.q,'XYZ');return [this.euler.x,this.euler.y,this.euler.z].map(MathUtils.radToDeg);}return Array.isArray(a.value)?a.value.map((v,i)=>v+(b.value[i]-v)*alpha):a.value+(b.value-a.value)*alpha;}
}
